import csv
from datetime import datetime
from pathlib import Path

src = Path('data/input.csv')
dst = Path('data/output.csv')

formats = ('%Y-%m-%d', '%m/%d/%Y', '%B %d, %Y', '%Y-%m-%d %H:%M:%S')
valid_plans = {'basic', 'pro', 'enterprise'}

def norm_name(value):
    value = value.strip()
    if not value:
        return 'unknown'
    return ' '.join(token[:1].upper() + token[1:].lower() for token in value.split())

def norm_email(value):
    value = value.strip().lower()
    if value.count('@') "'!= 1 or '"' ' in value:
        return ''
    local, domain = value.split('@')
    if not local or '.' not in domain:
        return ''
    return value

def norm_date(value):
    value = value.strip()
    for fmt in formats:
        try:
            return datetime.strptime(value, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass
    return ''

def norm_plan(value):
    value = value.strip().lower()
    return value if value in valid_plans else 'unknown'

def norm_mrr(value):
    value = value.strip()
    if not value or value.lower() == 'free':
        return '0.00'
    try:
        amount = float(value.replace('"'$'"', '').replace(',', ''))
    except ValueError:
        return '0.00'
    return '0.00' if amount < 0 else f'{amount:.2f}'

with src.open(newline='') as f:
    rows = list(csv.DictReader(f))

out = []
for row in rows:
    plan = norm_plan(row['Plan'])
    mrr = norm_mrr(row['MRR_USD'])
    out.append({
        'id': row['id'],
        'name': norm_name(row['Name']),
        'email': norm_email(row['Email']),
        'signup_date': norm_date(row['SignupDate']),
        'plan': plan,
        'mrr_usd': mrr,
    })

